adsorbat_dist = np.arange(len(adsorbat_gray))
substrat_dist = np.arange(len(substrat_gray))

# --- 1. Peak finden (Maximum) ---
# np.argmax findet den Index des höchsten Wertes
idx_adsorbat_peak = np.argmax(adsorbat_gray)
idx_substrat_peak = np.argmax(substrat_gray)

# --- 2. X-Achse verschieben ---
# Wir ziehen von jedem x-Wert die Position des Peaks ab.
# Dann ist der Peak bei x = 0.
x_adsorbat_centered = adsorbat_dist - adsorbat_dist[idx_adsorbat_peak]
x_substrat_centered = substrat_dist - substrat_dist[idx_substrat_peak]

# --- 3. Plotten ---
plt.figure(figsize=(10, 6))

plt.plot(x_adsorbat_centered, adsorbat_gray, label='Adsorbat (KCl)', color='rebeccapurple')
plt.plot(x_substrat_centered, substrat_gray, label='Substrat (Ag)', color='hotpink', linestyle='--')

plt.axvline(0, color='gray', linestyle=':', alpha=0.5, label='0. Ordnung (Zentrum)')

plt.xlabel('Abstand zum Hauptmaximum [Pixel]')
plt.ylabel('Intensität ')
plt.title('Vergleich der Reflexabstände Substrat und Adsorbat (Zentriert)')
plt.legend()
plt.grid(True, alpha=0.3)

# Speichern und Zeigen
plt.tight_layout()
plt.savefig("Vergleich der Reflexabstände Substrat und Adsorbat.pdf")
plt.show()